import numpy as np
p=np.loadtxt('answer.xyz',skiprows=2,usecols=(1,2,3))
def dist(i,j):return np.linalg.norm(p[i]-p[j])
def ang(i,j,k):
 a=p[i]-p[j];b=p[k]-p[j];return np.degrees(np.arccos(np.clip(np.dot(a,b)/np.linalg.norm(a)/np.linalg.norm(b),-1,1)))
for i in (1,12,23,26):print('Pd N',i,dist(0,i))
for a in [(1,0,12),(23,0,26),(1,0,23),(23,24,25),(26,27,28),(0,23,24),(0,26,27)]:print('angle',a,ang(*a))
